import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// The Rust library for Android: src/main/jniLibs/<abi>/libmtrx_ffi.so and the
// UniFFI bindings src/main/kotlin/uniffi/mtrx/mtrx.kt, both generated by
// scripts/build-android-ffi.sh, next to the committed AndroidPlatform.kt.
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
}

// The Kotlin part of rustls-platform-verifier must be the version of the
// crate rustls-platform-verifier-android the library was built with.
val rustlsPlatformVerifierVersion: String = run {
    val lock = providers.fileContents(rootProject.layout.projectDirectory.file("../../Cargo.lock"))
        .asText.get().lines()
    val name = lock.indexOfFirst { it.trim() == "name = \"rustls-platform-verifier-android\"" }
    check(name >= 0) { "rustls-platform-verifier-android is not in Cargo.lock" }
    lock[name + 1].trim().removePrefix("version = ").trim('"')
}

android {
    namespace = "org.mtrx.ffi"
    compileSdk = 36

    defaultConfig {
        minSdk = 26
        consumerProguardFiles("consumer-rules.pro")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_17)
    }
}

dependencies {
    // UniFFI calls the library through JNA (its types are in the bindings'
    // API); the aar has its native part.
    api("net.java.dev.jna:jna:${libs.versions.jna.get()}@aar")
    implementation(libs.kotlinx.coroutines.android)
    implementation(libs.androidx.annotation)
    implementation("org.rustls:rustls-platform-verifier:$rustlsPlatformVerifierVersion@aar")
}
